//! `hyve-serde` — the two codecs every `#[model]` speaks
//! (`docs/02-architecture.md` §2.3).
//!
//! - **Binary** ([`Binary`], [`access`]): `rkyv` archives with the family-wide
//!   format control (`little_endian` + `aligned` + `pointer_width_32`), always
//!   validated with `bytecheck` before access. Used by the fast rail.
//! - **JSON** ([`Json`], [`to_json`], [`from_json`]): a direct codec generated by
//!   `#[model]`. Lossless: integers outside JSON's exact range (±2^53) and
//!   non-finite floats travel as strings, so both rails carry the same values.
//!   Inputs are bounded in nesting depth and size.
//! - **Schema fingerprints** ([`Fingerprint`]): compile-time hashes of a type's
//!   wire layout plus the codec format, compared before using the fast rail.
//!
//! Generated code refers to `rkyv` only through [`__private`], so the `rkyv`
//! fork can later be vendored without breaking user crates.

mod binary;
mod error;
mod fingerprint;
pub mod json;

pub use binary::{AlignedBytes, Binary, access};
pub use error::{DecodeError, EncodeError};
pub use fingerprint::{FORMAT_FINGERPRINT, Fingerprint, fnv1a, mix};
pub use json::{Json, JsonLimits, JsonReader, JsonWriter, from_json, from_json_with, to_json};

#[doc(hidden)]
pub mod __private {
    pub use rkyv;
}
